<?php
/** Administrator-only printable local recovery handover; intentionally excludes selectors, reset links, tokens, hashes, and passwords. */
declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php';

$administrator = require_role(['admin']);
if (!local_password_recovery_is_available() || !recovery_verification_notes_are_available()) {
    http_response_code(503);
    exit('Password recovery verification records are not ready. Import the required recovery migrations first.');
}
$requestId = filter_var($_GET['request_id'] ?? null, FILTER_VALIDATE_INT, ['options' => ['min_range' => 1]]);
if (!$requestId) {
    http_response_code(400);
    exit('Choose a valid recovery request.');
}
$request = fetch_one('SELECT r.id, r.requested_at, r.verification_notes, r.verified_at, r.issued_at, r.expires_at, r.used_at, r.revoked_at, u.full_name, u.email, u.phone, role.name AS role_name, verifier.full_name AS verified_by_name, issuer.full_name AS issued_by_name, revoker.full_name AS revoked_by_name FROM local_password_recovery_requests r JOIN users u ON u.id = r.user_id JOIN roles role ON role.id = u.role_id LEFT JOIN users verifier ON verifier.id = r.verified_by_user_id LEFT JOIN users issuer ON issuer.id = r.issued_by_user_id LEFT JOIN users revoker ON revoker.id = r.revoked_by_user_id WHERE r.id = :request_id LIMIT 1', ['request_id' => $requestId]);
if ($request === null || $request['verified_at'] === null) {
    http_response_code(404);
    exit('A verified local recovery request was not found.');
}
$status = $request['used_at'] !== null ? 'Used' : ($request['revoked_at'] !== null ? 'Revoked' : ($request['issued_at'] !== null && strtotime((string) $request['expires_at']) > time() ? 'Active local reset issued' : ($request['issued_at'] !== null ? 'Expired' : 'Verified; awaiting issue')));
audit_log((int) $administrator['id'], 'local_recovery_handover_printed', 'local_password_recovery_requests', (int) $request['id']);
?>
<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Local recovery handover #<?= (int) $request['id'] ?> | <?= e(APP_NAME) ?></title><style>body{margin:0;background:#f6f3ea;color:#18251e;font:15px/1.55 Arial,sans-serif}.handover{max-width:760px;margin:34px auto;padding:32px;background:#fffdf8;border:1px solid #d5d8cf}.kicker{margin:0 0 9px;color:#194b35;font-size:11px;font-weight:700;letter-spacing:.08em;text-transform:uppercase}.kicker:before{display:inline-block;width:20px;height:2px;margin:0 7px 3px 0;background:#bd6845;content:"""}.handover h1{margin:0;color:#18251e;font:600 33px/1.08 Georgia,serif}.handover>p{max-width:640px;color:#647066}.status{display:inline-block;margin:6px 0 18px;padding:5px 9px;background:#e7eee5;color:#194b35;font-size:12px;font-weight:700}.record{margin:22px 0;border-top:2px solid #194b35}.record div{display:grid;grid-template-columns:185px 1fr;gap:18px;padding:12px 0;border-bottom:1px solid #d5d8cf}.record dt{color:#647066;font-size:12px;font-weight:700;text-transform:uppercase}.record dd{margin:0}.note{padding:14px 16px;border:1px solid #cbd8cb;background:#f1f6ee}.notice{margin-top:20px;padding:12px 14px;border-left:4px solid #bd6845;background:#f4eadf;color:#4a4037;font-size:13px}.actions{display:flex;gap:10px;margin-top:24px}.actions button,.actions a{padding:10px 13px;border:1px solid #194b35;background:#194b35;color:#fff;font:700 12px Arial,sans-serif;text-decoration:none;cursor:pointer}.actions a{background:#fffdf8;color:#194b35}@media print{body{background:#fff}.handover{margin:0;border:0;max-width:none}.actions{display:none}}</style></head><body><main class="handover"><p class="kicker">Quetta AgriLink · local recovery handover</p><h1>Verified recovery record #<?= (int) $request['id'] ?></h1><p>Use this local handover only after the approved offline identity review. It records recovery status and approved contact context, not reset credentials.</p><span class="status"><?= e($status) ?></span><dl class="record"><div><dt>Account holder</dt><dd><?= e($request['full_name']) ?></dd></div><div><dt>Role</dt><dd><?= e($request['role_name']) ?></dd></div><div><dt>Current contact</dt><dd><?= e($request['email']) ?> · <?= e($request['phone']) ?></dd></div><div><dt>Requested</dt><dd><?= e(date('j M Y H:i', strtotime((string) $request['requested_at']))) ?></dd></div><div><dt>Identity review</dt><dd>Recorded by <?= e($request['verified_by_name'] ?? 'administrator') ?> on <?= e(date('j M Y H:i', strtotime((string) $request['verified_at']))) ?></dd></div><div><dt>Reset lifecycle</dt><dd><?php if ($request['issued_at'] !== null): ?>Issued by <?= e($request['issued_by_name'] ?? 'administrator') ?> on <?= e(date('j M Y H:i', strtotime((string) $request['issued_at']))) ?><?php else: ?>No reset link has been issued.<?php endif; ?><?php if ($request['used_at'] !== null): ?><br>Used on <?= e(date('j M Y H:i', strtotime((string) $request['used_at']))) ?>.<?php endif; ?><?php if ($request['revoked_at'] !== null): ?><br>Revoked by <?= e($request['revoked_by_name'] ?? 'administrator') ?> on <?= e(date('j M Y H:i', strtotime((string) $request['revoked_at']))) ?>.<?php endif; ?></dd></div></dl><section class="note"><strong>Recorded verification context</strong><br><?= nl2br(e((string) $request['verification_notes'])) ?></section><p class="notice"><strong>Security boundary:</strong> This handover deliberately contains no password, reset link, selector, token, token hash, password hash, or secret. Share any active reset link only through the approved verified local process, not on this printed record.</p><div class="actions"><button type="button" onclick="window.print()">Print record</button><a href="<?= e(app_url('admin/password-recovery.php')) ?>">Return to recovery register</a></div></main></body></html>
